import{_ as e,C as s,o as i,c as g,a2 as t,E as n}from"./chunks/framework.CnHmQiA8.js";const h=JSON.parse('{"title":"编辑与排版","description":"","frontmatter":{"title":"编辑与排版","outline":[2,3]},"headers":[],"relativePath":"guide/editing.md","filePath":"guide/editing.md","lastUpdated":1795528411000}'),d={name:"guide/editing.md"};function a(l,o,_,c,u,T){const r=s("TutorialVideo");return i(),g("div",null,[o[0]||(o[0]=t('<h1 id="编辑与排版" tabindex="-1">编辑与排版 <a class="header-anchor" href="#编辑与排版" aria-label="Permalink to &quot;编辑与排版&quot;">​</a></h1><p>编辑界面的所有修改支持最多 <strong>200 步</strong> 撤销与重做（<code>Ctrl+Z</code> / <code>Ctrl+Y</code> / <code>Ctrl+Shift+Z</code>）。</p><h2 id="_1-题目、综合题与快捷排版" tabindex="-1">1. 题目、综合题与快捷排版 <a class="header-anchor" href="#_1-题目、综合题与快捷排版" aria-label="Permalink to &quot;1. 题目、综合题与快捷排版&quot;">​</a></h2>',3)),n(r,{id:"editing-question"}),o[1]||(o[1]=t('<ul><li><strong>难度与变式题</strong>：物理默认 <code>A～C</code> 三级（数学 <code>A～E</code> 五级），可在 <strong>版式设置 → 难度显示</strong> 切换；勾选 <strong>变式题</strong> 后题号编为 <code>a. b. c.</code>，不占数字题号。</li><li><strong>重点题与审题</strong>：在题目属性面板 <strong>仅教师版</strong> 页可勾选 <strong>重点题</strong> 与填写 <strong>审题</strong>；可在 <strong>版式设置 → 题目可选项</strong> 中按需开关。</li><li><strong>综合题</strong>：支持背景材料与配图，答案与解析可一键切换“集中在最后”或“分到各小题”；小题可通过上/下移、右键 <strong>移到</strong> 或大纲拖拽移入/移出综合题。</li><li><strong>作业单与分页编号</strong>：通过 <strong>添加</strong> 菜单插入 <strong>作业单</strong>（自动另起一页并带姓名栏、从 1 重编题号）；大标题/栏目标题/题型分组也可单独勾选“从新的一页开始”与“题号从 1 重新开始”。</li><li><strong>右键快捷与大纲拖拽</strong>：在预览或大纲右键题目/知识点可弹出快捷版式窗口；在大纲按住条目 <code>0.3 秒</code> 可拖拽排序（拖到综合题末尾偏右缩进即放进综合题，<code>Esc</code> 取消）。</li><li><strong>版式设置（大纲顶部）</strong>：分别控制教案/学案是否整题同页、行距倍数、以及选项列间距方案（可“另存为方案”复用）。</li></ul><h2 id="_2-知识点、表格与可视化公式" tabindex="-1">2. 知识点、表格与可视化公式 <a class="header-anchor" href="#_2-知识点、表格与可视化公式" aria-label="Permalink to &quot;2. 知识点、表格与可视化公式&quot;">​</a></h2>',2)),n(r,{id:"editing-formula-table"}),o[2]||(o[2]=t("<ul><li><strong>知识点与挖空重点</strong>：按“一、二、三……”分组，支持设置段后空行、从此段换页与拆分为新知识点；用格式工具栏最前面的 <strong>重点</strong> 按钮标红加粗下划线后，在 <strong>物理知识点手册</strong> 学生版中会自动挖空成横线用于默写。</li><li><strong>表格编辑</strong>：点击 <strong>插入表格 / 编辑表格</strong>，支持增删行列、<code>Shift</code> 连选合并、拆分单元格、按厘米设列宽或平均分布；在预览中可直接拖动表格竖线调列宽；题型整理预设下支持将学生版单元格设为虚线书写格。</li><li><strong>文字格式与填空</strong>：使用 <code>Ctrl+B / I / U</code>、颜色按钮（或在预览直接选中文字唤出浮动工具条）调整格式；连续输入至少 3 个下划线 <code>_</code> 即可生成填空横线（每 2 个下划线占 1 个字宽）；各输入框旁可独立选择宋/黑/楷/仿宋字体。</li><li><strong>可视化公式</strong>：点击 <strong>插入公式</strong> 插入新公式，在预览中点击任意公式即可打开可视化编辑面板与数学键盘；公式字母默认正体，可在 <strong>版式设置 → 公式字母</strong> 切换正斜体；未改动的 Word 原生公式导出时原样保留。</li></ul>",1))])}const m=e(d,[["render",a]]);export{h as __pageData,m as default};
